import{Ft as e,St as t,bt as n,ht as r,t as i,vt as a,xt as o,zt as s}from"./chunks/framework.B0CLzZNn.js";import"./chunks/assets.2zH0uHwH.js";var c=JSON.parse(`{"title":"动作 (Action)","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/extension/action.md","filePath":"v1/ecosystem/extension/action.md","lastUpdated":1793342047000}`),l={name:`ecosystem/extension/action.md`};function u(i,c,l,u,d,f){let p=s(`NolebasePageProperties`),m=s(`NolebaseGitChangelog`);return e(),a(`div`,null,[c[0]||=r(`h1`,{id:`动作-action`,tabindex:`-1`},[o(`动作 (Action) `),r(`a`,{class:`header-anchor`,href:`#动作-action`,"aria-label":`Permalink to “动作 (Action)”`},`​`)],-1),t(p),c[1]||=n(`<p>此插件可以自定义插件命令，传递指定的提示词给 ChatLuna 调用（从而实现自定义命令调用 llm）。并且可以拦截命令输出，调用 ChatLuna 来进行文字二次渲染。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><ul><li>前往插件市场搜索 <code>chatluna-actions</code> 并安装。</li></ul><p><img src="/images/image-83.png" alt="alt text" width="1178" height="524" loading="lazy"></p><p>完成完成后直接启用插件即可。</p><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h2><p>参考下面的插件配置，配置插件即可。</p><p>配置完成后记得启用插件，才能选择模型。</p><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to “配置项”">​</a></h2><p>此处列举了 <code>chatluna-actions</code> 插件的配置项。</p><h3 id="命令配置" tabindex="-1">命令配置 <a class="header-anchor" href="#命令配置" aria-label="Permalink to “命令配置”">​</a></h3><h4 id="command" tabindex="-1">command <a class="header-anchor" href="#command" aria-label="Permalink to “command”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：注册的一级命令名称</li></ul><h4 id="model" tabindex="-1">model <a class="header-anchor" href="#model" aria-label="Permalink to “model”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：执行命令时使用的模型</li></ul><h4 id="enabled" tabindex="-1">enabled <a class="header-anchor" href="#enabled" aria-label="Permalink to “enabled”">​</a></h4><ul><li>类型：<code>boolean</code></li><li>默认值：<code>false</code></li><li>描述：是否启用此命令</li></ul><h4 id="description" tabindex="-1">description <a class="header-anchor" href="#description" aria-label="Permalink to “description”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：命令的描述</li></ul><h4 id="chatmode" tabindex="-1">chatMode <a class="header-anchor" href="#chatmode" aria-label="Permalink to “chatMode”">​</a></h4><ul><li><p>类型：<code>chat|plugin</code></p></li><li><p>默认值：<code>chat</code></p></li><li><p>描述：聊天模式（chat: 聊天模式, plugin: Agent 模式）</p></li></ul><h4 id="prompttype" tabindex="-1">promptType <a class="header-anchor" href="#prompttype" aria-label="Permalink to “promptType”">​</a></h4><ul><li>类型：<code>Instruction|preset</code></li><li>默认值：<code>Instruction</code></li><li>描述：提示词类型（Instruction: 指令, preset: 预设）</li></ul><h4 id="preset" tabindex="-1">preset <a class="header-anchor" href="#preset" aria-label="Permalink to “preset”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：选择的预设</li></ul><h4 id="prompt" tabindex="-1">prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to “prompt”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：自定义提示词</li><li>说明：留空用户会自由输入，如设定不为空则使用设定值。</li></ul><h3 id="拦截命令配置" tabindex="-1">拦截命令配置 <a class="header-anchor" href="#拦截命令配置" aria-label="Permalink to “拦截命令配置”">​</a></h3><h4 id="interceptcommands" tabindex="-1">interceptCommands <a class="header-anchor" href="#interceptcommands" aria-label="Permalink to “interceptCommands”">​</a></h4><ul><li>类型：<code>string[]</code></li><li>默认值：无</li><li>描述：拦截的命令列表</li></ul><h4 id="interceptposition" tabindex="-1">interceptPosition <a class="header-anchor" href="#interceptposition" aria-label="Permalink to “interceptPosition”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：拦截的位置（after: 命令执行后, before: 命令执行前）</li></ul><h4 id="interceptenabled" tabindex="-1">interceptEnabled <a class="header-anchor" href="#interceptenabled" aria-label="Permalink to “interceptEnabled”">​</a></h4><ul><li>类型：<code>boolean</code></li><li>默认值：<code>false</code></li><li>描述：是否启用此拦截命令配置</li></ul><h4 id="interceptmodel" tabindex="-1">interceptModel <a class="header-anchor" href="#interceptmodel" aria-label="Permalink to “interceptModel”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：执行拦截命令时使用的模型</li></ul><h4 id="interceptcommand" tabindex="-1">interceptCommand <a class="header-anchor" href="#interceptcommand" aria-label="Permalink to “interceptCommand”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：拦截的命令名称</li></ul><h4 id="interceptchatmode" tabindex="-1">interceptChatMode <a class="header-anchor" href="#interceptchatmode" aria-label="Permalink to “interceptChatMode”">​</a></h4><ul><li>类型：<code>chat|plugin</code></li><li>默认值：<code>chat</code></li><li>描述：聊天模式（chat: 聊天模式, plugin: Agent 模式）</li></ul><h4 id="interceptprompttype" tabindex="-1">interceptPromptType <a class="header-anchor" href="#interceptprompttype" aria-label="Permalink to “interceptPromptType”">​</a></h4><ul><li>类型：<code>Instruction|preset</code></li><li>默认值：<code>Instruction</code></li><li>描述：提示词类型（Instruction: 指令, preset: 预设）</li></ul><h4 id="interceptpreset" tabindex="-1">interceptPreset <a class="header-anchor" href="#interceptpreset" aria-label="Permalink to “interceptPreset”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：选择的预设</li></ul><h4 id="interceptprompt" tabindex="-1">interceptPrompt <a class="header-anchor" href="#interceptprompt" aria-label="Permalink to “interceptPrompt”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：无</li><li>描述：自定义提示词</li><li>说明：拦截命令输入文本</li></ul>`,46),t(m)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};